import { expect, test } from "vitest";
import * as z from "zod/v4";

test("x", () => {
  let n = 0;
  const s = z.object({
    T: z.string().default(() => {
      n++;
      return "d";
    }),
  });
  s.parse({});
  expect(n).toBe(1);
  n = 0;
  s.parse({}, { jitless: true } as any);
  expect(n).toBe(1);
});

