import { expect, test } from "vitest";
import * as z from "zod/v4";

test("default factory runs once per object parse", () => {
  let n = 0;
  const s = z.object({
    a: z.string().default(() => `${n++}`),
    b: z.string().prefault(() => `${n++}`),
  });
  expect(s.parse({})).toEqual({ a: "0", b: "1" });
  expect(n).toBe(2);
});

